INSERT INTO `wp_posts` VALUES ('7','0','2026-11-10 07:22:06','2026-11-10 07:22:06','<h2>1. Tổng quan &amp; Điểm nhấn Đầu tư Dự án Đại Đô Thị Vinhomes Grand Park TP. Thủ Đức</h2><p>Đại đô thị thông minh quy mô 271ha tại tâm điểm TP. Thủ Đức với công viên 36ha và tuyến Vành Đai 3 đi xuyên tâm.</p><h2>2. Phân tích Vị trí &amp; Kết nối Hạ tầng</h2><p>Tọa lạc tại <strong>Nguyễn Xiển – Phước Thiện, P. Long Bình, TP. Thủ Đức, TP.HCM</strong>, dự án thừa hưởng trọn vẹn mạng lưới hạ tầng giao thông đồng bộ và khả năng gia tăng giá trị bền vững trong giai đoạn 2026 – 2030.</p><h2>3. Mặt bằng, Pháp lý &amp; Chính sách Bán hàng</h2><p>Tình trạng pháp lý: <strong>Sổ hồng lâu dài, GPXD &amp; Quy hoạch 1/500</strong>. Chính sách tài chính: <strong>Vietcombank, Techcombank hỗ trợ vay 70{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}, LS 0{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162} 24 tháng</strong>.</p>','Đại Đô Thị Vinhomes Grand Park TP. Thủ Đức','Đại đô thị thông minh quy mô 271ha tại tâm điểm TP. Thủ Đức với công viên 36ha và tuyến Vành Đai 3 đi xuyên tâm.','publish','open','closed','','vinhomes-grand-park','','','2026-11-10 07:39:27','2026-11-10 07:39:27','','0','http://localhost/www/kenhbds/du-an/vinhomes-grand-park/','0','du_an','','0');
INSERT INTO `wp_posts` VALUES ('8','0','2026-11-10 07:22:06','2026-11-10 07:22:06','<h2>Thông tin chi tiết sản phẩm GH-BE2-1508</h2><p>Sản phẩm đã được đội ngũ Kênh Bất Động Sản kiểm duyệt thực tế về pháp lý (<strong>HĐMB chính chủ - Sang tên ngay</strong>), diện tích <strong>79.2 m²</strong> và mức giá chào bán <strong>4.15 tỷ (Bao thuế phí)</strong>.</p>','Căn góc 2PN+1 The Beverly View Trực Diện Công Viên 36ha','','publish','closed','closed','','can-goc-2pn-the-beverly-view-cong-vien','','','2026-11-10 07:39:27','2026-11-10 07:39:27','','0','http://localhost/www/kenhbds/mua-ban/can-goc-2pn-the-beverly-view-cong-vien/','0','bat_dong_san','','0');
