INSERT INTO `wp_posts` VALUES ('11','0','2026-11-10 07:39:27','2026-11-10 07:39:27','<h2>1. Tổng quan &amp; Điểm nhấn Đầu tư Dự án Đại Đô Thị Vinhomes Grand Park TP. Thủ Đức</h2><p>Đại đô thị thông minh quy mô 271ha tại tâm điểm TP. Thủ Đức với công viên 36ha và tuyến Vành Đai 3 đi xuyên tâm.</p><h2>2. Phân tích Vị trí &amp; Kết nối Hạ tầng</h2><p>Tọa lạc tại <strong>Nguyễn Xiển – Phước Thiện, P. Long Bình, TP. Thủ Đức, TP.HCM</strong>, dự án thừa hưởng trọn vẹn mạng lưới hạ tầng giao thông đồng bộ và khả năng gia tăng giá trị bền vững trong giai đoạn 2026 – 2030.</p><h2>3. Mặt bằng, Pháp lý &amp; Chính sách Bán hàng</h2><p>Tình trạng pháp lý: <strong>Sổ hồng lâu dài, GPXD &amp; Quy hoạch 1/500</strong>. Chính sách tài chính: <strong>Vietcombank, Techcombank hỗ trợ vay 70{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}, LS 0{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162} 24 tháng</strong>.</p>','Đại Đô Thị Vinhomes Grand Park TP. Thủ Đức','Đại đô thị thông minh quy mô 271ha tại tâm điểm TP. Thủ Đức với công viên 36ha và tuyến Vành Đai 3 đi xuyên tâm.','inherit','closed','closed','','7-revision-v1','','','2026-11-10 07:39:27','2026-11-10 07:39:27','','7','http://localhost/www/kenhbds/?p=11','0','revision','','0');
