INSERT INTO `wp_posts` VALUES ('13','0','2026-11-10 07:39:27','2026-11-10 07:39:27','<h2>1. Tổng quan &amp; Điểm nhấn Đầu tư Dự án Khu Đô Thị The Global City – Trung Tâm Mới TP.HCM</h2><p>Khu đô thị phức hợp chuẩn quốc tế 117.4ha thiết kế bởi Foster + Partners ngay nút giao An Phú, Phường An Phú, TP. Thủ Đức.</p><h2>2. Phân tích Vị trí &amp; Kết nối Hạ tầng</h2><p>Tọa lạc tại <strong>Đỗ Xuân Hợp – Cao tốc Long Thành, P. An Phú, TP. Thủ Đức, TP.HCM</strong>, dự án thừa hưởng trọn vẹn mạng lưới hạ tầng giao thông đồng bộ và khả năng gia tăng giá trị bền vững trong giai đoạn 2026 – 2030.</p><h2>3. Mặt bằng, Pháp lý &amp; Chính sách Bán hàng</h2><p>Tình trạng pháp lý: <strong>Pháp lý hoàn chỉnh, Sổ hồng lâu dài</strong>. Chính sách tài chính: <strong>Techcombank, VPBank tài trợ 80{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}, ân hạn gốc 24 tháng</strong>.</p>','Khu Đô Thị The Global City – Trung Tâm Mới TP.HCM','Khu đô thị phức hợp chuẩn quốc tế 117.4ha thiết kế bởi Foster + Partners ngay nút giao An Phú, Phường An Phú, TP. Thủ Đức.','publish','open','closed','','the-global-city-masterise','','','2026-11-10 07:39:27','2026-11-10 07:39:27','','0','http://localhost/www/kenhbds/du-an/the-global-city-masterise/','0','du_an','','0');
