INSERT INTO `wp_posts` VALUES ('25','0','2026-11-10 07:39:27','2026-11-10 07:39:27','<h2>Thông tin chi tiết sản phẩm GH-EP-A2201</h2><p>Sản phẩm đã được đội ngũ Kênh Bất Động Sản kiểm duyệt thực tế về pháp lý (<strong>HĐMB trực tiếp Gamuda Land</strong>), diện tích <strong>104.8 m²</strong> và mức giá chào bán <strong>12.9 tỷ (Thanh toán 5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}/đợt)</strong>.</p>','Suất Nội Bộ Căn Góc 3PN Eaton Park Tầng Cao View Sông Thoáng Mát','','publish','closed','closed','','can-3pn-eaton-park-view-song-suat-f1','','','2026-11-10 07:39:27','2026-11-10 07:39:27','','0','http://localhost/www/kenhbds/mua-ban/can-3pn-eaton-park-view-song-suat-f1/','0','bat_dong_san','','0');
