INSERT INTO `wp_posts` VALUES ('102','1','2026-11-10 09:12:33','2026-11-10 09:12:33','[section label=\"1. Hero Banner Vinhomes King Park\" bg=\"127\" bg_size=\"original\" bg_overlay=\"rgba(7, 25, 46, 0.78)\" dark=\"true\" padding=\"56px\"]\n\n[row style=\"large\" v_align=\"middle\"]\n\n[col span=\"7\" span__sm=\"12\"]\n\n<div style=\"display:inline-flex;align-items:center;gap:8px;border:1px solid #E5C158;color:#FDE68A;padding:6px 16px;border-radius:99px;font-size:12.5px;font-weight:700;letter-spacing:0.6px;margin-bottom:16px\">\n	<span>👑 TÂM ĐIỂM SỐNG &amp; NGHỈ DƯỠNG MỚI TẠI KINH BẮC • BÁN ĐẢO HÒA LONG</span>\n</div>\n\n<h1 style=\"font-size:36px;font-weight:800;line-height:1.25;color:#ffffff;margin:0 0 16px\">Vinhomes King Park Bắc Ninh – Đại Đô Thị Sân Golf 90ha &amp; Sinh Thái 268,8ha Bên Sông Cầu</h1>\n\n<p style=\"font-size:16px;line-height:1.7;color:#e2e8f0;margin-bottom:24px\">Được kiến tạo bởi <strong>Chủ đầu tư Liên doanh Vingroup</strong> và <strong>Đơn vị phát triển MIK Group</strong>, <strong>Vinhomes King Park</strong> sở hữu mật độ xây dựng chỉ <strong>18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</strong> với <strong>101,69 ha cây xanh – mặt nước</strong>, dòng <strong>sông Cầu</strong> ôm trọn phía Bắc cùng tuyệt tác <strong>Sân Golf 18 lỗ rộng 90 ha</strong> ngay trên bán đảo Hòa Long.</p>\n\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:28px\">\n	<div style=\"border-radius:10px;padding:12px 14px\">\n		<strong style=\"display:block;font-size:22px;font-weight:800;color:#E5C158\">268,8 ha</strong>\n		<span style=\"font-size:12.5px;color:#cbd5e1\">Tổng diện tích đất</span>\n	</div>\n	<div style=\"border-radius:10px;padding:12px 14px\">\n		<strong style=\"display:block;font-size:22px;font-weight:800;color:#4ADE80\">101,69 ha</strong>\n		<span style=\"font-size:12.5px;color:#cbd5e1\">Cây xanh &amp; Mặt nước</span>\n	</div>\n	<div style=\"border-radius:10px;padding:12px 14px\">\n		<strong style=\"display:block;font-size:22px;font-weight:800;color:#38BDF8\">90 ha</strong>\n		<span style=\"font-size:12.5px;color:#cbd5e1\">Sân Golf 18 lỗ Hòa Long</span>\n	</div>\n	<div style=\"border-radius:10px;padding:12px 14px\">\n		<strong style=\"display:block;font-size:22px;font-weight:800;color:#FBBF24\">18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</strong>\n		<span style=\"font-size:12.5px;color:#cbd5e1\">Mật độ xây dựng</span>\n	</div>\n</div>\n\n[button text=\"📥 Nhận Bảng Giá &amp; Mặt Bằng 1/500\" color=\"secondary\" size=\"larger\" radius=\"8\" link=\"#nhan-bang-gia\"]\n[button text=\"📞 Hotline Tư Vấn: 0942.655.111\" style=\"outline\" color=\"white\" size=\"larger\" radius=\"8\" link=\"tel:0942655111\"]\n\n[/col]\n\n[col span=\"5\" span__sm=\"12\"]\n\n[kbds_quick_lead_card title=\"ĐĂNG KÝ NHẬN BỘ TÀI LIỆU GỐC\" subtitle=\"Nhận Bảng giá dự kiến, Bản đồ quy hoạch bán đảo Hòa Long 268,8ha &amp; Lịch mở bán Quý III/2026 qua Zalo:\" project=\"Vinhomes King Park Bắc Ninh\"]\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"2. Thanh Điều Hướng Nhanh (Quick Jump)\" bg_color=\"#ffffff\" padding=\"14px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div class=\"kbds-proj-nav\">\n	<a href=\"#tong-quan\">📋 1. Tổng Quan &amp; Thông Số</a>\n	<a href=\"#vi-tri\">📍 2. Vị Trí Bán Đảo Hòa Long</a>\n	<a href=\"#tien-ich\">⛳ 3. Sân Golf 90ha &amp; Tiện Ích</a>\n	<a href=\"#san-pham\">🏛️ 4. Quy Mô &amp; Loại Hình Sản Phẩm</a>\n	<a href=\"#bang-gia-lai-vay\">🧮 5. Tiến Độ, Giỏ Hàng &amp; Lãi Vay</a>\n	<a href=\"#faq\">❓ 6. Câu Hỏi Thường Gặp</a>\n	<a href=\"#tin-tuc-du-an\">📰 7. Tin Tức &amp; Đánh Giá</a>\n	<a href=\"#nhan-bang-gia\" class=\"kbds-nav-cta\">📥 Tải Bảng Giá Ngay</a>\n</div>\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"3. Tổng Quan Dự Án &amp; Thông Số Kỹ Thuật\" bg_color=\"#F8F9FA\" padding=\"60px\"]\n\n[row style=\"large\" v_align=\"top\"]\n\n[col span=\"7\" span__sm=\"12\"]\n\n<div id=\"tong-quan\"></div>\n<span class=\"kbds-sub-badge\">HỒ SƠ PHÁP LÝ &amp; QUY HOẠCH TỔNG THỂ</span>\n<h2 style=\"color:#0B2C4D;font-size:28px;font-weight:800;margin:0 0 16px;line-height:1.3\">1. Tổng Quan Dự Án Vinhomes King Park Bắc Ninh – Biểu Tượng Sống \"Xanh Dương\"</h2>\n\n<p style=\"font-size:15.5px;line-height:1.75;color:#334155\"><strong>Vinhomes King Park</strong> được định vị trở thành tâm điểm sống và nghỉ dưỡng mới tại vùng đất di sản <strong>Kinh Bắc</strong> nói riêng và tỉnh <strong>Bắc Ninh</strong> nói chung. Dự án là sự kết hợp chiến lược giữa <strong>Chủ đầu tư Công ty liên doanh Vingroup</strong> và <strong>Đơn vị phát triển dự án MIK Group</strong> trên tổng quỹ đất rộng tới <strong>268,8 ha</strong> tại bán đảo Hòa Long.</p>\n\n<p style=\"font-size:15.5px;line-height:1.75;color:#334155\">Điểm tạo nên sức hút đặc biệt của <strong>dự án Vinhomes King Park Bắc Ninh</strong> nằm ở triết lý quy hoạch sinh thái mật độ cực thấp: <strong>mật độ xây dựng toàn khu chỉ 18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</strong>. Phần lớn diện tích được ưu tiên cho thiên nhiên với tổng diện tích cây xanh và mặt nước bên trong khu đô thị (bao gồm công viên nội khu và sông hồ nội khu) lên tới <strong>101,69 ha</strong>, kết hợp cùng dòng <strong>sông Cầu</strong> ôm trọn phía Bắc khu đô thị, kiến tạo chuẩn sống <em>“Xanh dương”</em> đẳng cấp – nơi con người được hòa mình giữa miền thiên nhiên thuần khiết.</p>\n\n<div style=\"background:#ffffff;border-left:4px solid #C59B27;border-radius:10px;padding:18px 20px;margin:20px 0\">\n	<h3 style=\"color:#0B2C4D;font-size:18px;font-weight:800;margin:0 0 8px\">👑 Ý nghĩa tên gọi \"Vinhomes King Park\"</h3>\n	<p style=\"margin:0;font-size:15px;line-height:1.65;color:#475569\">Ngoài việc từ <strong>“King Park”</strong> là cách đọc lái đầy tự hào của vùng đất văn hiến <strong>“Kinh Bắc”</strong>, tên gọi dự án còn lấy cảm hứng trực tiếp từ đại công viên sinh thái và <strong>sân golf 18 lỗ rộng lên tới 90 ha</strong> nằm gọn bên trong bán đảo Hòa Long – biểu tượng sống vương giả lần đầu tiên xuất hiện tại Bắc Ninh.</p>\n</div>\n\n<div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:20px\">\n	<div class=\"kbds-ux-card\" style=\"padding:16px 18px\">\n		<strong style=\"color:#0B2C4D;font-size:15px;display:block;margin-bottom:4px\">🏛️ Bảo chứng từ Vingroup &amp; MIK Group</strong>\n		<span style=\"font-size:13.5px;color:#64748b;line-height:1.5;display:block\">Tiến độ thần tốc, chất lượng xây dựng vượt trội và chuẩn vận hành đô thị thông minh hàng đầu Việt Nam.</span>\n	</div>\n	<div class=\"kbds-ux-card\" style=\"padding:16px 18px\">\n		<strong style=\"color:#0E8A4A;font-size:15px;display:block;margin-bottom:4px\">🌿 Tỷ lệ Xanh &amp; Mặt nước kỷ lục</strong>\n		<span style=\"font-size:13.5px;color:#64748b;line-height:1.5;display:block\">101,69 ha công viên – hồ nội khu cùng 90 ha sân golf Hòa Long tạo vi khí hậu trong lành quanh năm.</span>\n	</div>\n</div>\n\n[/col]\n\n[col span=\"5\" span__sm=\"12\"]\n\n<div style=\"background:#ffffff;border:2px solid #0B2C4D;border-radius:14px;overflow:hidden\">\n	<div style=\"background:linear-gradient(135deg,#0B2C4D 0{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162},#164B7D 100{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162});color:#ffffff;padding:18px 22px;display:flex;justify-content:space-between;align-items:center\">\n		<div>\n			<span style=\"font-size:11.5px;color:#E5C158;font-weight:700;letter-spacing:0.5px;display:block\">BẢNG THÔNG SỐ CHÍNH THỨC</span>\n			<strong style=\"font-size:18px\">Hồ Sơ Dự Án Vinhomes King Park</strong>\n		</div>\n		<span style=\"background:#C59B27;color:#fff;padding:5px 12px;border-radius:8px;font-weight:800;font-size:13.5px\">⭐ 9.5/10</span>\n	</div>\n	<div style=\"padding:8px 20px 18px\">\n		<table style=\"width:100{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162};border-collapse:collapse;font-size:14px\">\n			<tbody>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569;width:42{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}\">Tên thương mại:</td>\n					<td style=\"padding:11px 4px;font-weight:800;color:#0B2C4D\">Vinhomes King Park</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Vị trí dự án:</td>\n					<td style=\"padding:11px 4px;color:#1e293b;font-weight:600\">Bán đảo Hòa Long (Ven sông Cầu), Bắc Ninh</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Chủ đầu tư:</td>\n					<td style=\"padding:11px 4px;color:#1e293b;font-weight:700\">Công ty liên doanh Vingroup</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Đơn vị phát triển:</td>\n					<td style=\"padding:11px 4px;color:#1e293b;font-weight:700\">MIK Group</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Tổng diện tích đất:</td>\n					<td style=\"padding:11px 4px;font-weight:800;color:#0B2C4D\">268,8 ha</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Mật độ xây dựng:</td>\n					<td style=\"padding:11px 4px;font-weight:800;color:#0E8A4A\">18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Cây xanh &amp; mặt nước:</td>\n					<td style=\"padding:11px 4px;font-weight:700;color:#0284C7\">101,69 ha + Sông Cầu phía Bắc</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Tiện ích điểm nhấn:</td>\n					<td style=\"padding:11px 4px;font-weight:700;color:#1e293b\">Sân Golf 18 lỗ (90 ha), Vincom, Vinschool, Vinmec</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Quy mô phát triển:</td>\n					<td style=\"padding:11px 4px;color:#1e293b\"><strong>8 tòa căn hộ</strong> &amp; <strong>4.222 căn thấp tầng</strong></td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Loại hình Cao tầng:</td>\n					<td style=\"padding:11px 4px;color:#1e293b\">Studio, 1PN, 1PN+1, 2PN, 2PN+1, 3PN</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Loại hình Thấp tầng:</td>\n					<td style=\"padding:11px 4px;color:#1e293b\">Biệt thự đơn lập, song lập, liền kề, shophouse</td>\n				</tr>\n				<tr style=\"border-bottom:1px solid #e2e8f0\">\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Thời điểm khởi công:</td>\n					<td style=\"padding:11px 4px;font-weight:700;color:#D92D20\">Quý III/2026</td>\n				</tr>\n				<tr>\n					<td style=\"padding:11px 4px;font-weight:600;color:#475569\">Thời điểm bàn giao:</td>\n					<td style=\"padding:11px 4px;font-weight:700;color:#0E8A4A\">Năm 2027</td>\n				</tr>\n			</tbody>\n		</table>\n		<div style=\"margin-top:14px;text-align:center\">\n			<a href=\"#nhan-bang-gia\" style=\"display:block;background:#0B2C4D;color:#ffffff;font-weight:700;padding:12px;border-radius:8px;text-decoration:none;font-size:14px\">📥 Tải File PDF Hồ Sơ Quy Hoạch Dự Án</a>\n		</div>\n	</div>\n</div>\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"4. Vị Trí Bán Đảo Hòa Long &amp; Phong Thủy Sông Cầu\" bg_color=\"#ffffff\" padding=\"60px\"]\n\n[row style=\"large\" v_align=\"middle\"]\n\n[col span=\"6\" span__sm=\"12\"]\n\n<div id=\"vi-tri\"></div>\n[ux_image id=\"128\" image_size=\"original\" caption=\"true\"]\n\n[/col]\n\n[col span=\"6\" span__sm=\"12\"]\n\n<span class=\"kbds-sub-badge\">TỌA ĐỘ PHONG THỦY ĐỘC TÔN TẠI BẮC NINH</span>\n<h2 style=\"color:#0B2C4D;font-size:28px;font-weight:800;margin:0 0 16px;line-height:1.3\">2. Vị Trí Dự Án Vinhomes King Park – Bán Đảo Hòa Long Ôm Trọn Bởi Dòng Sông Cầu</h2>\n\n<p style=\"font-size:15.5px;line-height:1.75;color:#334155\">Tọa lạc tại <strong>bán đảo Hòa Long, TP. Bắc Ninh</strong>, <strong>Vinhomes King Park</strong> sở hữu địa thế tự nhiên hiếm có khi toàn bộ <strong>phía Bắc khu đô thị được dòng sông Cầu lịch sử ôm trọn</strong>. Trong phong thủy phương Đông, thế đất bán đảo được dòng sông lớn bao bọc mang lại vượng khí sinh tài lộc, đồng thời tạo lập vành đai sinh thái biệt lập, yên bình ngay sát trung tâm đô thị.</p>\n\n<ul style=\"font-size:15px;line-height:1.8;color:#334155;padding-left:20px;margin-bottom:22px\">\n	<li><strong>Tâm điểm kết nối Kinh Bắc:</strong> Di chuyển nhanh chóng vào trung tâm hành chính – thương mại TP. Bắc Ninh chỉ trong vài phút qua hệ thống đại lộ mở rộng.</li>\n	<li><strong>Cửa ngõ đón sóng chuyên gia quốc tế:</strong> Kết nối trực tiếp tới các Khu công nghiệp trọng điểm tại Bắc Ninh – Bắc Giang (Samsung, Amkor, Foxconn, Goertek...), nơi làm việc của hơn 50.000 kỹ sư và chuyên gia nước ngoài.</li>\n	<li><strong>Liên kết vùng toàn diện:</strong> Thuận tiện di chuyển về Thủ đô Hà Nội, sân bay quốc tế Nội Bài và tam giác kinh tế phía Bắc thông qua mạng lưới cao tốc &amp; vành đai hiện đại.</li>\n</ul>\n\n[button text=\"🗺️ Nhận Bản Đồ Quy Hoạch Giao Thông Hòa Long\" color=\"primary\" size=\"large\" radius=\"8\" link=\"#nhan-bang-gia\"]\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"5. Hệ Sinh Thái Tiện Ích All-in-One &amp; Sân Golf 90ha\" bg_color=\"#0B2C4D\" dark=\"true\" padding=\"64px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div id=\"tien-ich\" style=\"text-align:center;max-width:820px;margin:0 auto 36px\">\n	<span style=\"display:inline-block;border:1px solid #E5C158;color:#FDE68A;padding:5px 16px;border-radius:99px;font-size:12px;font-weight:700;letter-spacing:0.6px;margin-bottom:12px\">HỆ SINH THÁI ALL-IN-ONE ĐẲNG CẤP VINGROUP</span>\n	<h2 style=\"color:#ffffff;font-size:30px;font-weight:800;margin:0 0 12px\">3. Hệ Thống Tiện Ích Vinhomes King Park: Sân Golf 90ha &amp; 101,69ha Cây Xanh Mặt Nước</h2>\n	<p style=\"color:#cbd5e1;font-size:15.5px;line-height:1.65;margin:0\">Sở hữu chuẩn sống nghỉ dưỡng 365 ngày với hệ sinh thái tiện ích khép kín chuẩn quốc tế lần đầu tiên quy tụ đầy đủ tại bán đảo Hòa Long, Bắc Ninh.</p>\n</div>\n\n[/col]\n\n[/row]\n\n[row style=\"normal\"]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">⛳</div>\n	<h3 style=\"color:#E5C158;font-size:19px;font-weight:800;margin:0 0 10px\">Sân Golf 18 Lỗ Rộng 90 ha</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Nằm gọn bên trong bán đảo Hòa Long, sân golf 18 lỗ quy mô 90 ha không chỉ là nơi giao lưu của giới thượng lưu mà còn mở ra tầm nhìn xanh mát triệu đô cho các phân khu biệt thự và căn hộ.</p>\n</div>\n[/col]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">🌊</div>\n	<h3 style=\"color:#4ADE80;font-size:19px;font-weight:800;margin:0 0 10px\">101,69 ha Cây Xanh &amp; Mặt Nước</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Bao gồm chuỗi công viên nội khu chủ đề và hệ thống sông hồ nội khu rộng lớn, kết hợp dòng sông Cầu phía Bắc mang lại cuộc sống \"Xanh dương\" thanh khiết.</p>\n</div>\n[/col]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">🛍️</div>\n	<h3 style=\"color:#38BDF8;font-size:19px;font-weight:800;margin:0 0 10px\">TTTM Vincom &amp; Phố Shophouse</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Tâm điểm mua sắm, giải trí, rạp chiếu phim, ẩm thực cao cấp tại trung tâm thương mại Vincom cùng các dãy nhà phố thương mại Shophouse sầm uất ngày đêm.</p>\n</div>\n[/col]\n\n[/row]\n\n[row style=\"normal\"]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">🎓</div>\n	<h3 style=\"color:#FDE68A;font-size:19px;font-weight:800;margin:0 0 10px\">Trường Học Liên Cấp Vinschool</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Môi trường giáo dục chuẩn quốc tế ngay trong nội khu, giúp thế hệ tương lai tại Kinh Bắc phát triển toàn diện cả trí tuệ, thể chất lẫn kỹ năng hội nhập toàn cầu.</p>\n</div>\n[/col]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">🏥</div>\n	<h3 style=\"color:#F87171;font-size:19px;font-weight:800;margin:0 0 10px\">Bệnh Viện Quốc Tế Vinmec</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Hệ thống y tế và chăm sóc sức khỏe tiêu chuẩn quốc tế Vinmec với trang thiết bị tối tân, bảo vệ sức khỏe 24/7 cho mọi thành viên trong gia đình.</p>\n</div>\n[/col]\n\n[col span=\"4\" span__sm=\"12\"]\n<div class=\"kbds-ux-card-dark\">\n	<div style=\"font-size:28px;margin-bottom:10px\">🏊</div>\n	<h3 style=\"color:#A7F3D0;font-size:19px;font-weight:800;margin:0 0 10px\">Công Viên Nội Khu &amp; Thể Thao</h3>\n	<p style=\"color:#e2e8f0;font-size:14.5px;line-height:1.65;margin:0\">Chuỗi bể bơi resort, đường dạo bộ ven sông hồ, sân thể thao liên hoàn, vườn BBQ và bến cảnh quan phục vụ đặc quyền cho cư dân.</p>\n</div>\n[/col]\n\n[/row]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n<div style=\"text-align:center;margin-top:16px\">\n	<p style=\"color:#cbd5e1;font-size:14.5px;margin-bottom:14px\">👉 Xem bài phân tích chuyên sâu: <a href=\"http://localhost/www/kenhbds/tien-ich-du-an-vinhomes-king-park-bac-ninh-san-golf-90ha-he-sinh-thai-10169ha-cay-xanh-mat-nuoc/\" style=\"color:#E5C158;font-weight:700;text-decoration:underline\">Chi tiết hệ thống tiện ích dự án Vinhomes King Park Bắc Ninh &amp; Sân Golf 90ha</a></p>\n</div>\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"6. Quy Mô Phát Triển &amp; Cơ Cấu Sản Phẩm\" bg_color=\"#F8F9FA\" padding=\"60px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div id=\"san-pham\" style=\"text-align:center;max-width:820px;margin:0 auto 32px\">\n	<span class=\"kbds-sub-badge\">QUY MÔ PHÁT TRIỂN ĐA DẠNG</span>\n	<h2 style=\"color:#0B2C4D;font-size:28px;font-weight:800;margin:0 0 12px\">4. Mặt Bằng &amp; Các Loại Hình Sản Phẩm Tại Vinhomes King Park</h2>\n	<p style=\"color:#475569;font-size:15.5px;line-height:1.65;margin:0\">Trên quỹ đất <strong>268,8 ha</strong> với mật độ xây dựng chỉ <strong>18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</strong>, dự án phát triển gồm <strong>8 tòa căn hộ cao tầng</strong> và <strong>4.222 căn nhà ở thấp tầng</strong> đáp ứng trọn vẹn nhu cầu ở thực, nghỉ dưỡng lẫn đầu tư sinh lời.</p>\n</div>\n\n[/col]\n\n[/row]\n\n[row style=\"large\" v_align=\"stretch\"]\n\n[col span=\"6\" span__sm=\"12\"]\n<div class=\"kbds-ux-card\" style=\"border-top:5px solid #0B2C4D\">\n	<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px\">\n		<span style=\"background:#EFF6FF;color:#1D4ED8;font-weight:700;font-size:12px;padding:4px 12px;border-radius:99px\">PHÂN KHU CAO TẦNG</span>\n		<strong style=\"color:#0B2C4D;font-size:18px;font-weight:800\">Quy mô: 8 Tòa Căn Hộ</strong>\n	</div>\n	<h3 style=\"color:#0B2C4D;font-size:21px;font-weight:800;margin:0 0 12px\">Tổ Hợp 8 Tòa Căn Hộ Cao Cấp View Sông &amp; Sân Golf</h3>\n	<p style=\"color:#475569;font-size:14.5px;line-height:1.65;margin-bottom:16px\">Thiết kế mặt thoáng kính tràn Panorama ôm trọn tầm nhìn 101,69 ha cây xanh mặt nước, dòng sông Cầu và sân golf 90 ha. Tối ưu công năng cho cả gia đình trẻ lẫn nhà đầu tư khai thác cho thuê chuyên gia FDI:</p>\n	<table style=\"width:100{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162};border-collapse:collapse;font-size:14px;margin-bottom:18px\">\n		<thead>\n			<tr style=\"background:#F1F5F9;color:#0B2C4D\">\n				<th style=\"padding:9px 12px;text-align:left\">Loại hình căn hộ</th>\n				<th style=\"padding:9px 12px;text-align:left\">Đối tượng &amp; Khai thác tối ưu</th>\n			</tr>\n		</thead>\n		<tbody>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Căn hộ Studio</td>\n				<td style=\"padding:9px 12px\">Vốn đầu tư nhỏ, thanh khoản nhanh, cho thuê chuyên gia độc thân</td>\n			</tr>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Căn hộ 1PN &amp; 1PN+1</td>\n				<td style=\"padding:9px 12px\">Không gian đa năng (+1), tỷ suất dòng tiền cho thuê cao nhất</td>\n			</tr>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Căn hộ 2PN &amp; 2PN+1</td>\n				<td style=\"padding:9px 12px\">Dòng sản phẩm chủ đạo cho gia đình trẻ &amp; chuyên gia cấp quản lý</td>\n			</tr>\n			<tr>\n				<td style=\"padding:9px 12px;font-weight:700\">Căn hộ 3PN Góc</td>\n				<td style=\"padding:9px 12px\">Căn góc 2 mặt thoáng view trực diện Sân Golf 90ha &amp; Sông Cầu</td>\n			</tr>\n		</tbody>\n	</table>\n	<a href=\"#nhan-bang-gia\" style=\"display:inline-block;background:#0B2C4D;color:#fff;font-weight:700;padding:10px 20px;border-radius:8px;text-decoration:none;font-size:13.5px\">📥 Nhận Layout Bóc Tách 8 Tòa Căn Hộ →</a>\n</div>\n[/col]\n\n[col span=\"6\" span__sm=\"12\"]\n<div class=\"kbds-ux-card\" style=\"border-top:5px solid #C59B27\">\n	<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px\">\n		<span style=\"background:#FDF8EC;color:#9A7312;font-weight:700;font-size:12px;padding:4px 12px;border-radius:99px\">PHÂN KHU THẤP TẦNG</span>\n		<strong style=\"color:#C59B27;font-size:18px;font-weight:800\">Quy mô: 4.222 Căn</strong>\n	</div>\n	<h3 style=\"color:#0B2C4D;font-size:21px;font-weight:800;margin:0 0 12px\">4.222 Căn Biệt Thự Sinh Thái, Liền Kề &amp; Shophouse</h3>\n	<p style=\"color:#475569;font-size:14.5px;line-height:1.65;margin-bottom:16px\">Tọa lạc giữa những bán đảo cây xanh, hồ cảnh quan nội khu và kế cận sân golf 18 lỗ rộng 90 ha, phân khu thấp tầng là tài sản truyền đời khẳng định vị thế chủ nhân:</p>\n	<table style=\"width:100{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162};border-collapse:collapse;font-size:14px;margin-bottom:18px\">\n		<thead>\n			<tr style=\"background:#FDF8EC;color:#9A7312\">\n				<th style=\"padding:9px 12px;text-align:left\">Loại hình thấp tầng</th>\n				<th style=\"padding:9px 12px;text-align:left\">Giá trị độc bản tại bán đảo Hòa Long</th>\n			</tr>\n		</thead>\n		<tbody>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Biệt thự Đơn lập</td>\n				<td style=\"padding:9px 12px\">Vị trí kim cương ven sông hồ &amp; sân golf 90ha, sân vườn rộng</td>\n			</tr>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Biệt thự Song lập</td>\n				<td style=\"padding:9px 12px\">Kiến trúc sang trọng, 3 mặt thoáng xanh mát kế cận công viên</td>\n			</tr>\n			<tr style=\"border-bottom:1px solid #e2e8f0\">\n				<td style=\"padding:9px 12px;font-weight:700\">Nhà ở Liền kề</td>\n				<td style=\"padding:9px 12px\">Tối ưu diện tích sử dụng, không gian sống văn minh khép kín</td>\n			</tr>\n			<tr>\n				<td style=\"padding:9px 12px;font-weight:700\">Nhà phố Shophouse</td>\n				<td style=\"padding:9px 12px\">Mặt trục đường lớn &amp; kế cận Vincom, vừa ở vừa kinh doanh đắc lộc</td>\n			</tr>\n		</tbody>\n	</table>\n	<a href=\"#nhan-bang-gia\" style=\"display:inline-block;background:#C59B27;color:#fff;font-weight:700;padding:10px 20px;border-radius:8px;text-decoration:none;font-size:13.5px\">📥 Nhận Bản Đồ Phân Lô 4.222 Căn Thấp Tầng →</a>\n</div>\n[/col]\n\n[/row]\n\n[row style=\"large\"]\n[col span=\"12\" span__sm=\"12\"]\n[ux_image id=\"129\" image_size=\"original\" caption=\"true\"]\n[/col]\n[/row]\n\n[/section]\n\n[section label=\"7. Tiến Độ 2026-2027, Giỏ Hàng &amp; Tính Lãi Vay\" bg_color=\"#ffffff\" padding=\"60px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div id=\"bang-gia-lai-vay\"></div>\n<span class=\"kbds-sub-badge\">LỘ TRÌNH TRIỂN KHAI &amp; TÀI CHÍNH ĐẦU TƯ</span>\n<h2 style=\"color:#0B2C4D;font-size:28px;font-weight:800;margin:0 0 20px\">5. Tiến Độ Dự Án Vinhomes King Park (2026 – 2027) &amp; Bảng Tính Dòng Tiền</h2>\n\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:32px\">\n	<div style=\"background:#F8FAFC;border:1px solid #CBD5E1;border-top:4px solid #0B2C4D;border-radius:12px;padding:20px\">\n		<span style=\"font-size:12px;font-weight:800;color:#0B2C4D;background:#E2E8F0;padding:3px 10px;border-radius:99px\">CỘT MỐC 1</span>\n		<h3 style=\"color:#0B2C4D;font-size:19px;font-weight:800;margin:10px 0 6px\">Quý III/2026: Khởi Công Dự Án</h3>\n		<p style=\"font-size:14px;color:#475569;margin:0;line-height:1.6\">Chính thức khởi công hạ tầng tổng thể 268,8 ha tại bán đảo Hòa Long, triển khai cảnh quan 101,69 ha cây xanh mặt nước và sân golf 90 ha.</p>\n	</div>\n	<div style=\"background:#F8FAFC;border:1px solid #CBD5E1;border-top:4px solid #C59B27;border-radius:12px;padding:20px\">\n		<span style=\"font-size:12px;font-weight:800;color:#9A7312;background:#FDF8EC;padding:3px 10px;border-radius:99px\">CỘT MỐC 2</span>\n		<h3 style=\"color:#0B2C4D;font-size:19px;font-weight:800;margin:10px 0 6px\">Cuối 2026 – 2027: Thi Công Thần Tốc</h3>\n		<p style=\"font-size:14px;color:#475569;margin:0;line-height:1.6\">Đồng loạt thi công 8 tòa căn hộ, 4.222 căn biệt thự/liền kề/shophouse cùng hệ sinh thái Vincom, Vinschool, Vinmec dưới sự phát triển của MIK Group.</p>\n	</div>\n	<div style=\"background:#F8FAFC;border:1px solid #CBD5E1;border-top:4px solid #0E8A4A;border-radius:12px;padding:20px\">\n		<span style=\"font-size:12px;font-weight:800;color:#0E8A4A;background:#DCFCE7;padding:3px 10px;border-radius:99px\">CỘT MỐC 3</span>\n		<h3 style=\"color:#0B2C4D;font-size:19px;font-weight:800;margin:10px 0 6px\">Năm 2027: Bàn Giao &amp; Vận Hành</h3>\n		<p style=\"font-size:14px;color:#475569;margin:0;line-height:1.6\">Dự kiến bàn giao nhà cho cư dân ngay trong năm 2027, đưa Vinhomes King Park trở thành tâm điểm sống &amp; nghỉ dưỡng sôi động bậc nhất Bắc Ninh.</p>\n	</div>\n</div>\n\n[kbds_project_listings project_id=\"102\" limit=\"6\"]\n\n[kbds_loan_calculator]\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"8. Câu Hỏi Thường Gặp (FAQ Chuẩn SEO)\" bg_color=\"#F8F9FA\" padding=\"60px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div id=\"faq\"></div>\n<span class=\"kbds-sub-badge\">GIẢI ĐÁP THẮC MẮC NHÀ ĐẦU TƯ</span>\n<h2 style=\"color:#0B2C4D;font-size:28px;font-weight:800;margin:0 0 20px\">6. Câu Hỏi Thường Gặp Về Dự Án Vinhomes King Park Bắc Ninh</h2>\n\n[accordion]\n\n[accordion-item title=\"1. Chủ đầu tư và đơn vị phát triển dự án Vinhomes King Park Bắc Ninh là ai?\"]\n<p>Dự án <strong>Vinhomes King Park</strong> do <strong>Công ty liên doanh Vingroup</strong> làm Chủ đầu tư và được phát triển bởi <strong>MIK Group</strong> – hai thương hiệu bất động sản uy tín hàng đầu Việt Nam bảo chứng cho pháp lý, tiến độ và chất lượng vận hành.</p>\n[/accordion-item]\n\n[accordion-item title=\"2. Tổng diện tích và mật độ xây dựng của Vinhomes King Park là bao nhiêu?\"]\n<p>Tổng diện tích đất của dự án Vinhomes King Park là <strong>268,8 ha</strong> tại bán đảo Hòa Long, Bắc Ninh. Đặc biệt, mật độ xây dựng toàn khu chỉ chiếm <strong>18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}</strong>, dành tới <strong>101,69 ha</strong> cho cây xanh và mặt nước nội khu (công viên nội khu &amp; sông hồ nội khu) cùng <strong>90 ha</strong> cho sân golf 18 lỗ.</p>\n[/accordion-item]\n\n[accordion-item title=\"3. Dự án Vinhomes King Park Bắc Ninh có những loại hình sản phẩm nào?\"]\n<p>Quy mô phát triển của dự án bao gồm 2 dòng sản phẩm chính:</p>\n<ul>\n	<li><strong>Phân khu Cao tầng (8 tòa căn hộ):</strong> Đa dạng diện tích gồm Studio, 1PN, 1PN+1, 2PN, 2PN+1 và 3PN.</li>\n	<li><strong>Phân khu Thấp tầng (4.222 căn):</strong> Gồm Biệt thự đơn lập, Biệt thự song lập, Liền kề và Nhà phố thương mại Shophouse.</li>\n</ul>\n[/accordion-item]\n\n[accordion-item title=\"4. Hệ thống tiện ích Vinhomes King Park có gì đặc biệt?\"]\n<p>Dự án sở hữu hệ sinh thái <strong>“All-in-one”</strong> đẳng cấp gồm: Trung tâm thương mại <strong>Vincom</strong>, trường học liên cấp <strong>Vinschool</strong>, bệnh viện quốc tế <strong>Vinmec</strong>, hệ thống công viên &amp; sông hồ nội khu <strong>101,69 ha</strong>, dòng <strong>sông Cầu</strong> ôm trọn phía Bắc và nổi bật nhất là <strong>sân golf 18 lỗ rộng 90 ha</strong> nằm gọn bên trong bán đảo Hòa Long.</p>\n[/accordion-item]\n\n[accordion-item title=\"5. Thời điểm khởi công và bàn giao dự án Vinhomes King Park là khi nào?\"]\n<p>Theo kế hoạch triển khai, dự án Vinhomes King Park Bắc Ninh có thời điểm khởi công vào <strong>Quý III/2026</strong> và dự kiến bàn giao vào <strong>Năm 2027</strong>.</p>\n[/accordion-item]\n\n[/accordion]\n\n[/col]\n\n[/row]\n\n[/section]\n\n[section label=\"9. Form Đăng Ký Nhận Bảng Giá &amp; Chính Sách\" bg_color=\"#ffffff\" padding=\"50px\"]\n\n[row]\n\n[col span=\"12\" span__sm=\"12\"]\n\n<div id=\"nhan-bang-gia\"></div>\n[kbds_lead_form title=\"📥 Đăng Ký Nhận Bảng Giá Gốc, Mặt Bằng 1/500 &amp; Chính Sách Ưu Đãi Vinhomes King Park\" project=\"Vinhomes King Park Bắc Ninh\"]\n\n[/col]\n\n[/row]\n\n[/section]','Vinhomes King Park Bắc Ninh','Vinhomes King Park Bắc Ninh (268,8ha) tại bán đảo Hòa Long do Vingroup &amp; MIK Group phát triển: Mật độ xây dựng 18,5{9d9051bf5beb045ce62abf0b108d65b642f3f4c1aa6244b26df1e326ead4f162}, 101,69ha cây xanh mặt nước, sân golf 18 lỗ 90ha, 8 tòa căn hộ &amp; 4.222 căn thấp tầng.','publish','open','closed','','vinhomes-king-park','','','2026-11-12 03:09:42','2026-11-12 03:09:42','','0','http://localhost/www/kenhbds/?post_type=du_an&#038;p=102','0','du_an','','0');
